class Inkling2LoopFullLoopDecoderLayer(GradientCheckpointingLayer):
    attention_type = "full_attention"

    def __init__(self, config: Inkling2LoopTextConfig, layer_idx: int):
        super().__init__()
        self.is_block_boundary = layer_idx % config.n_layers_per_attn_res_block == 0
        self.attention_input = Inkling2LoopBlockAttentionResidual(config, num_queries=3) if layer_idx > 0 else None
        self.mlp_input = Inkling2LoopBlockAttentionResidual(config)
        self.self_attn = Inkling2LoopFullAttention(config, layer_idx)
        self.mlp = Inkling2LoopSparseMoeBlock(config)
        self.q_input_layernorm = Inkling2LoopRMSNorm(config.hidden_size, config.rms_norm_eps)
        self.k_input_layernorm = Inkling2LoopRMSNorm(config.hidden_size, config.rms_norm_eps)
        self.v_input_layernorm = Inkling2LoopRMSNorm(config.hidden_size, config.rms_norm_eps)
        self.post_attention_layernorm = Inkling2LoopRMSNorm(config.hidden_size, config.rms_norm_eps)
        self.post_attention_convolution = Inkling2LoopShortConvolution(
            config.hidden_size, config.conv_kernel_size, layer_idx=layer_idx, conv_idx=2
        )
        self.post_mlp_convolution = Inkling2LoopShortConvolution(
            config.hidden_size, config.conv_kernel_size, layer_idx=layer_idx, conv_idx=3
        )
        self.q_message_gate = Inkling2LoopMessageGate(config)
        self.k_message_gate = Inkling2LoopMessageGate(config)
        self.v_message_gate = Inkling2LoopMessageGate(config)
        self.mlp_message_gate = Inkling2LoopMessageGate(config)

    @deprecate_kwarg("past_key_values", "5.40.0", new_name="cache")
    def forward(
        self,
        hidden_states: torch.Tensor,
        block_states: torch.Tensor,
        messages: torch.Tensor | None = None,
        attention_mask: torch.Tensor | None = None,
        relative_distance: torch.Tensor | None = None,
        conv_mask: torch.Tensor | None = None,
        cache: Cache | None = None,
        cache_offset: int = 0,
        **kwargs: Unpack[TransformersKwargs],
    ) -> torch.Tensor:
        r"""
        messages (`torch.Tensor` of shape `(batch_size, sequence_length, 4, hidden_size)`, *optional*):
            Messages of the previous pass through the loop layers for the query, key, value and MLP inputs, in the
            passes after the first.
        cache_offset (`int`, *optional*, defaults to 0):
            Offset added to `layer_idx` to get the cache layer holding the keys, values and convolution states of
            this call.
        """
        dtype = hidden_states.dtype
        block_residual = hidden_states
        query_hidden_states, key_hidden_states, value_hidden_states = self.attention_input(block_states, hidden_states)

        if messages is not None:
            query_message, key_message, value_message, mlp_message = messages.unbind(-2)
            query_hidden_states = self.q_message_gate(query_hidden_states, query_message)
            key_hidden_states = self.k_message_gate(key_hidden_states, key_message)
            value_hidden_states = self.v_message_gate(value_hidden_states, value_message)

        hidden_states, _ = self.self_attn(
            hidden_states=self.q_input_layernorm(query_hidden_states).to(dtype),
            key_hidden_states=self.k_input_layernorm(key_hidden_states).to(dtype),
            value_hidden_states=self.v_input_layernorm(value_hidden_states).to(dtype),
            attention_mask=attention_mask,
            relative_distance=relative_distance,
            conv_mask=conv_mask,
            cache=cache,
            cache_offset=cache_offset,
            **kwargs,
        )
        hidden_states = self.post_attention_convolution(
            hidden_states, cache=cache, conv_mask=conv_mask, cache_offset=cache_offset, **kwargs
        )

        residual = hidden_states = hidden_states.float()
        if self.is_block_boundary:
            block_states = torch.cat([block_states, block_residual.unsqueeze(-2)], dim=-2)
        else:
            residual = hidden_states = block_residual.float() + hidden_states

        hidden_states = self.mlp_input(block_states, hidden_states)[0]
        if messages is not None:
            hidden_states = self.mlp_message_gate(hidden_states, mlp_message)
        hidden_states = self.mlp(self.post_attention_layernorm(hidden_states).to(dtype))
        hidden_states = self.post_mlp_convolution(
            hidden_states, cache=cache, conv_mask=conv_mask, cache_offset=cache_offset, **kwargs
        )
        return (residual + hidden_states).to(dtype)


class Inkling2LoopTopKRouter(nn.Module):
    def __init__(self, config: Inkling2LoopConfig):
        super().__init__()
        self.top_k = config.num_experts_per_tok
        self.num_experts = config.num_local_experts
        self.hidden_dim = config.hidden_size
        self.weight = nn.Parameter(torch.empty(self.num_experts, self.hidden_dim))
        self.score_fn = ACT2FN[config.scoring_func]
        self.routed_scaling_factor = config.routed_scaling_factor
        self.e_score_correction_bias = nn.Buffer(torch.zeros(self.num_experts))

    def forward(self, hidden_states: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        # routing runs in fp32, as in the original
        hidden_states = hidden_states.float()
        flat = hidden_states.reshape(-1, self.hidden_dim)
        logits = F.linear(flat, self.weight)
        scores = self.score_fn(logits)
        indices = torch.topk(scores + self.e_score_correction_bias, self.top_k, dim=-1, sorted=False).indices
        weights = scores.gather(1, indices)
        weights = weights / (weights.sum(dim=-1, keepdim=True) + 1e-20)
        return logits, weights * self.routed_scaling_factor, indices


@auto_docstring
class Inkling2LoopPreTrainedModel(PreTrainedModel):
    config: Inkling2LoopConfig
    base_model_prefix = "model"
    supports_gradient_checkpointing = True
    _no_split_modules = [
        "Inkling2LoopSlidingDecoderLayer",
        "Inkling2LoopFullDecoderLayer",
        "Inkling2LoopSlidingLoopDecoderLayer",
        "Inkling2LoopFullLoopDecoderLayer",
    ]
    _skip_keys_device_placement = ["cache"]
    # Disabled because of the per-token attention sinks
    _supports_flash_attn = False
    _supports_sdpa = False
    _supports_flex_attn = False
    _can_compile_fullgraph = False
    _supports_attention_backend = False
    _keep_in_fp32_modules_strict = [
        "e_score_correction_bias",
        "mlp.gate.weight",
        "post_attention_convolution",
        "post_mlp_convolution",
        "sconv.conv1d",
        "attention_input",
        "mlp_input",
        "final_input",
        "message_input",
        "message_gate_proj",
        "forget_gate_proj",
    ]
    _can_record_outputs = {
        "hidden_states": OutputRecorder(
            (
                Inkling2LoopSlidingDecoderLayer,
                Inkling2LoopFullDecoderLayer,
                Inkling2LoopSlidingLoopDecoderLayer,
                Inkling2LoopFullLoopDecoderLayer,
            ),
            num_hidden_layers_key="total_num_hidden_layers",
        ),
        "attentions": [Inkling2LoopSlidingAttention, Inkling2LoopFullAttention],
        "router_logits": OutputRecorder(Inkling2LoopTopKRouter, index=0),
    }

    def _init_weights(self, module):
        super()._init_weights(module)
        std = self.config.get_text_config().initializer_range
        if isinstance(module, Inkling2LoopRelativePositionBias):
            init.normal_(module.proj, mean=0.0, std=std)
        elif isinstance(module, Inkling2LoopExperts):
            init.normal_(module.gate_up_proj, mean=0.0, std=std)
            init.normal_(module.down_proj, mean=0.0, std=std)
        elif isinstance(module, Inkling2LoopTopKRouter):
            init.normal_(module.weight, mean=0.0, std=std)
            init.zeros_(module.e_score_correction_bias)
        elif isinstance(module, (Inkling2LoopScaledL2Clip, Inkling2LoopLogScaledL2Clip)):
            init.ones_(module.scale)
        elif isinstance(module, Inkling2LoopDynamicShortConvolution):
            init.zeros_(module.static_weight)
        elif isinstance(module, Inkling2LoopBlockAttentionResidual):
            init.zeros_(module.query)
        if isinstance(module, Inkling2LoopMessageAttentionResidual):
            init.zeros_(module.query)


class Inkling2LoopNormedEmbedding(nn.Embedding):
    def __init__(self, num_embeddings: int, embedding_dim: int, padding_idx: int, norm_eps: float):
        super().__init__(num_embeddings, embedding_dim, padding_idx)
        self.embed_norm = Inkling2LoopRMSNorm(embedding_dim, eps=norm_eps)

    def forward(self, input_ids: torch.Tensor):
        return self.embed_norm(super().forward(input_ids))


def get_relative_distance(inputs_embeds: torch.Tensor, cache: Cache | None, is_sliding: bool) -> torch.Tensor:
    """
    Distance from each query position to each key position, of shape `(query_length, key_length)`, for the full or
    sliding attention layers. The sizes and offsets come from the same cache layer as for the attention masks.
    """
    q_length = inputs_embeds.shape[1]
    if cache is None:
        kv_length, kv_offset, q_offset = q_length, 0, 0
    else:
        if not is_sliding:
            layer_idx = find_first_full_attention_index(cache)
        elif True in cache.is_sliding:
            layer_idx = cache.is_sliding.index(True)
        else:
            layer_idx = 0
        kv_length, kv_offset = cache.get_mask_sizes(q_length, layer_idx)
        q_offset = cache.get_query_offset(layer_idx)
    q_positions = torch.arange(q_length, device=inputs_embeds.device) + q_offset
    kv_positions = torch.arange(kv_length, device=inputs_embeds.device) + kv_offset
    return q_positions[:, None] - kv_positions[None, :]


@auto_docstring
class Inkling2LoopTextModel(Inkling2LoopPreTrainedModel):
    config: Inkling2LoopTextConfig

    def __init__(self, config: Inkling2LoopTextConfig):
        super().__init__(config)
        self.padding_idx = config.pad_token_id
        self.vocab_size = config.vocab_size

        self.embed_tokens = Inkling2LoopNormedEmbedding(
            config.vocab_size, config.hidden_size, self.padding_idx, config.rms_norm_eps
        )
        self.layers = nn.ModuleList()
        self.norm = Inkling2LoopRMSNorm(config.hidden_size, eps=config.rms_norm_eps)
        self.gradient_checkpointing = False
        self.final_input = Inkling2LoopBlockAttentionResidual(config)
        layer_classes = {
            # (is_sliding, is_loop_layer)
            (False, False): Inkling2LoopFullDecoderLayer,
            (True, False): Inkling2LoopSlidingDecoderLayer,
            (False, True): Inkling2LoopFullLoopDecoderLayer,
            (True, True): Inkling2LoopSlidingLoopDecoderLayer,
        }
        for layer_idx in range(config.num_hidden_layers):
            is_sliding = config.layer_types[layer_idx] == "hybrid_sliding"
            is_loop_layer = config.loop_layer_index_start <= layer_idx < config.loop_layer_index_end
            layer_class = layer_classes[(is_sliding, is_loop_layer)]
            self.layers.append(layer_class(config, layer_idx))
        self.message_input = Inkling2LoopMessageAttentionResidual(config)

        # Initialize weights and apply final processing
        self.post_init()

    @merge_with_config_defaults
    @capture_outputs
    @auto_docstring
    @deprecate_kwarg("past_key_values", "5.40.0", new_name="cache")
    def forward(
        self,
        input_ids: torch.LongTensor | None = None,
        attention_mask: torch.Tensor | None = None,
        position_ids: torch.LongTensor | None = None,
        cache: Cache | None = None,
        inputs_embeds: torch.Tensor | None = None,
        use_cache: bool | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> MoeModelOutputWithPast:
        if (input_ids is None) ^ (inputs_embeds is not None):
            raise ValueError("You must specify exactly one of input_ids or inputs_embeds")

        if inputs_embeds is None:
            inputs_embeds = self.embed_tokens(input_ids)

        if use_cache and cache is None:
            cache = DynamicCache(config=self.config)

        if position_ids is None:
            past_seen_tokens = cache.get_seq_length() if cache is not None else 0
            position_ids = torch.arange(inputs_embeds.shape[1], device=inputs_embeds.device) + past_seen_tokens
            position_ids = position_ids.unsqueeze(0)

        if not isinstance(causal_mask_mapping := attention_mask, dict):
            mask_kwargs = {
                "config": self.config,
                "inputs_embeds": inputs_embeds,
                "attention_mask": attention_mask,
                "cache": cache,
                "position_ids": position_ids,
            }
            causal_mask_mapping = {
                "full_attention": create_causal_mask(**mask_kwargs),
                "sliding_attention": create_sliding_window_causal_mask(**mask_kwargs),
                "linear_attention": create_recurrent_attention_mask(**mask_kwargs),
            }
        relative_distance_mapping = {
            "full_attention": get_relative_distance(inputs_embeds, cache, is_sliding=False),
            "sliding_attention": get_relative_distance(inputs_embeds, cache, is_sliding=True),
        }

        loop_start = self.config.loop_layer_index_start
        loop_end = self.config.loop_layer_index_end
        num_loop_layers = loop_end - loop_start

        if cache is not None and len(cache.layers) == self.config.num_hidden_layers:
            # Append extra caches for loop layers
            loop_cache_layers = cache.layers[loop_start:loop_end]
            cache.layers += [copy.deepcopy(layer) for layer in loop_cache_layers * (self.config.loop_num_passes - 1)]

        hidden_states = inputs_embeds
        block_states = inputs_embeds.new_zeros(*inputs_embeds.shape[:-1], 0, inputs_embeds.shape[-1])

        # Pre loop layers
        for decoder_layer in self.layers[:loop_start]:
            new_hidden_states = decoder_layer(
                hidden_states,
                block_states,
                attention_mask=causal_mask_mapping[decoder_layer.attention_type],
                relative_distance=relative_distance_mapping[decoder_layer.attention_type],
                conv_mask=causal_mask_mapping["linear_attention"],
                cache=cache,
                position_ids=position_ids,
                **kwargs,
            )
            if decoder_layer.is_block_boundary:
                block_states = torch.cat([block_states.to(hidden_states.device), hidden_states.unsqueeze(-2)], dim=-2)
            hidden_states = new_hidden_states

        pre_loop_hidden_states, pre_loop_block_states = hidden_states, block_states
        num_pre_loop_blocks = pre_loop_block_states.shape[-2]

        # First pass over loop layers
        for decoder_layer in self.layers[loop_start:loop_end]:
            new_hidden_states = decoder_layer(
                hidden_states,
                block_states,
                attention_mask=causal_mask_mapping[decoder_layer.attention_type],
                relative_distance=relative_distance_mapping[decoder_layer.attention_type],
                conv_mask=causal_mask_mapping["linear_attention"],
                cache=cache,
                position_ids=position_ids,
                **kwargs,
            )
            if decoder_layer.is_block_boundary:
                block_states = torch.cat([block_states.to(hidden_states.device), hidden_states.unsqueeze(-2)], dim=-2)
            hidden_states = new_hidden_states

        # Remaining passes restart from the pre loop states and receive messages from the previous pass
        for loop_idx in range(1, self.config.loop_num_passes):
            # +1 to skip the states appended by the first loop pass
            previous_block_states = block_states[..., num_pre_loop_blocks + 1 :, :]
            previous_hidden_states = hidden_states
            hidden_states, block_states = pre_loop_hidden_states, pre_loop_block_states

            # Each pass uses its own copies of the loop cache layers, appended after the model's layers
            cache_offset = self.config.num_hidden_layers + (loop_idx - 1) * num_loop_layers - loop_start
            for loop_layer_idx, decoder_layer in enumerate(self.layers[loop_start:loop_end]):
                messages = self.message_input(previous_block_states, previous_hidden_states, loop_layer_idx)
                new_hidden_states = decoder_layer(
                    hidden_states,
                    block_states,
                    messages,
                    attention_mask=causal_mask_mapping[decoder_layer.attention_type],
                    relative_distance=relative_distance_mapping[decoder_layer.attention_type],
                    conv_mask=causal_mask_mapping["linear_attention"],
                    cache=cache,
                    cache_offset=cache_offset,
                    position_ids=position_ids,
                    **kwargs,
                )
                if decoder_layer.is_block_boundary:
                    block_states = torch.cat(
                        [block_states.to(hidden_states.device), hidden_states.unsqueeze(-2)], dim=-2
                    )
                hidden_states = new_hidden_states

        # Post loop layers
        for decoder_layer in self.layers[loop_end:]:
            new_hidden_states = decoder_layer(
                hidden_states,
                block_states,
                attention_mask=causal_mask_mapping[decoder_layer.attention_type],
                relative_distance=relative_distance_mapping[decoder_layer.attention_type],
                conv_mask=causal_mask_mapping["linear_attention"],
                cache=cache,
                position_ids=position_ids,
                **kwargs,
            )
            if decoder_layer.is_block_boundary:
                block_states = torch.cat([block_states.to(hidden_states.device), hidden_states.unsqueeze(-2)], dim=-2)
            hidden_states = new_hidden_states

        hidden_states = self.final_input(block_states, hidden_states)[0]
        hidden_states = self.norm(hidden_states).to(inputs_embeds.dtype)
        return MoeModelOutputWithPast(
            last_hidden_state=hidden_states,
            cache=cache,
        )


